"""30 konkrete Ausbauideen. Kleinster Test und spätere Zusatzverbindungen getrennt."""
IDEAS=[]
def add(group,title,start,steps,result,test,extras):
 IDEAS.append(dict(n=len(IDEAS)+1,group=group,title=title,start=start,steps=steps,result=result,test=test,extras=extras))
add('Marketing','Ein Ideenpostfach, das Ordnung hält','Neue freigegebene Themenidee','Idee einlesen → Thema und Kanal zuordnen → internen Zettel erzeugen','Ein klarer Vorschlag für den Redaktionsplan.','Workflow 2: thema auf „Blick hinter die Druckkulissen“ und kanal auf „Instagram“ ändern.','Später ein freigegebenes Formular oder Tabellenkonto; kein Social-Publishing nötig.')
add('Marketing','Ein Newsletter-Briefing statt leerer Seite','Ein Termin steht fest','Bestätigte Fakten sammeln → Ausgabe strukturieren → Redaktion prüft','Datum, Zielgruppe und Thema in einem Briefing.','Workflow 2 mit „Ideenatelier am 06.11.“ und „Newsletter“. Termin muss unverändert bleiben.','Später eigenes Newsletter-Werkzeug; Versand bleibt gesondert freizugeben.')
add('Marketing','Freigegebene Kampagnen sichtbar machen','Kampagne erhält eine Freigabe','Status prüfen → nur freigegebene Fälle weiterlassen','Ein interner Hinweis auf startbereite Arbeit.','Workflow 3 mit kategorie=MARKETING; Filter passend ändern, true und false vergleichen.','Später ein bestehender Projekttracker; keine Werbung automatisch buchen.')
add('Marketing','Ein Linkzettel für Kampagnen','Eine Kampagne bekommt einen bestätigten Link','Name und Zieladresse einlesen → beschrifteten Linkzettel bauen','Eine leicht prüfbare Übergabe für das Team.','Im zweiten Modul feste Labels „Kampagne“ und „Zieladresse“ ergänzen; echte URL nur als Testtext verwenden.','Für Klickmessung später erlaubte Analyse und sauber definierte Linkparameter; keine Reichweite versprechen.')
add('Marketing','Alte Ideen erneut vorlegen','Ein vorhandenes Thema soll wieder geprüft werden','Thema und Prüfdatum sammeln → Wiedervorlage-Zettel','Ein Vorschlag zur erneuten redaktionellen Prüfung.','Workflow 2: „Workshop-Foto erneut prüfen“, Kanal „Wiedervorlage“. Das ist noch kein Zeitplan.','Später Datumsfilter oder Projektkalender; Bildrechte und Aktualität vorher prüfen.')

add('Videoproduktion','Ein Drehbriefing aus vier Angaben','Ein kleines Videoprojekt beginnt','Projekt, Thema und Ausspielweg einlesen → Briefing','Ein lesbarer Zettel für den ersten Austausch.','Workflow 2 mit „Nordlicht“, „Interview vorbereiten“, „Drehplanung“.','Für längere Briefings später weitere bestätigte Felder; keine Videodatei nötig.')
